// Enhanced random with timestamp seed
const seed = Date.now() + Math.random() * 1000;
const randomIndex = Math.floor(seed % items.length);
const selectedItem = items[randomIndex];

return [{ json: selectedItem.json }];

const items = $input.all();
const scoredItems = [];

for (const item of items) {
  const feedItem = item.json;
  let score = 0;

  // Skip if no title or link
  if (!feedItem.title || !feedItem.link) continue;

  // Score based on how recent (simple version)
  const pubDate = new Date(feedItem.pubDate || feedItem.date);
  const now = new Date();
  const hoursOld = (now - pubDate) / (1000 * 60 * 60);

  if (hoursOld <= 24) score += 5;
  else if (hoursOld <= 48) score += 3;
  else score += 1;

  // Score based on title keywords (customize these)
  const title = (feedItem.title || '').toLowerCase();
  const keywords = ['ai', 'tech', 'innovation', 'startup', 'emerging tech', 'jobs of the future'];

  keywords.forEach(keyword => {
    if (title.includes(keyword)) score += 2;
  });

  scoredItems.push({
    title: feedItem.title,
    link: feedItem.link,
    description: feedItem.description,
    pubDate: feedItem.pubDate,
    score: score
  });
}

// Get top 3
const topItems = scoredItems
  .sort((a, b) => b.score - a.score)
  .slice(0, 15)
  .map(item => ({ json: item }));

return topItems;

return items.map(item => {
  // 1) Get the raw string from the AI
  let text = item.json.output;

  if (typeof text !== 'string') {
    throw new Error('Expected item.json.output to be a string, got ' + typeof text);
  }

  // 2) Strip possible ```json ... ``` code fences
  text = text.replace(/```json/gi, '')
             .replace(/```/g, '')
             .trim();

  // 3) Parse JSON from the cleaned text
  let data;
  try {
    data = JSON.parse(text);
  } catch (e) {
    throw new Error('Could not parse JSON from output: ' + e.message + '\nRaw text:\n' + text);
  }

  // 4) Get and normalize the category slug
  let slug = (data.category_slug || data.category || '').toString().trim().toLowerCase();
  slug = slug.replace(/\s+/g, '-').replace(/_/g, '-');
  if (slug === 'ai') slug = 'artificial-intelligence';

  const slugToId = {
    'artificial-intelligence': 52,
    'latest-news': 24,
    'metaverse': 54,
    'publications': 60,
    'research': 61,
    'sustainability': 69,
    'technology': 32,
    'web3': 56,
    'web-3': 56,
    'uncategorized': 1
  };

  const category_id = slugToId[slug] ?? 1;

  // 5) Generate post slug from title (or from model-provided slug if present)
  let postSlugSource = data.post_slug || data.slug || data.title || '';
  postSlugSource = postSlugSource.toString().toLowerCase();

  // Remove accents
  let post_slug = postSlugSource
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '');

  // Replace non-alphanumeric with dashes
  post_slug = post_slug.replace(/[^a-z0-9]+/g, '-');

  // Trim leading/trailing dashes and collapse multiple dashes
  post_slug = post_slug.replace(/^-+|-+$/g, '').replace(/-+/g, '-');

  // 🔥 Limit slug length (max 60 chars, cut on dash if possible)
  const MAX_SLUG_LENGTH = 60;

  if (post_slug.length > MAX_SLUG_LENGTH) {
    let truncated = post_slug.slice(0, MAX_SLUG_LENGTH);
    const lastDash = truncated.lastIndexOf('-');
    if (lastDash > 20) {
      truncated = truncated.slice(0, lastDash);
    }
    post_slug = truncated.replace(/-+$/g, '');
  }

  // 6) Return clean item
  return {
    json: {
      title: data.title,
      content: data.content,
      category_slug: slug,
      category_id,
      post_slug
    }
  };
});

// n8n "Function" node — Dynamic structuring of research text
// Output: one item with json = structured_data

// ---------- utilities ----------
function text(v) {
  if (v == null) return "";
  if (typeof v === "string") return v;
  try { return JSON.stringify(v, null, 2); } catch { return String(v); }
}
function norm(s="") {
  return s
    .replace(/\r/g, "")
    .replace(/[ \t]+\n/g, "\n")
    .replace(/\n{3,}/g, "\n\n")
    .trim();
}
function firstNonEmptyLine(s="") {
  const line = s.split(/\n/).map(l=>l.trim()).find(Boolean);
  return line || "";
}
function uniq(arr) {
  return Array.from(new Set(arr.filter(Boolean)));
}
function pickTitle(obj, raw) {
  if (obj && typeof obj.title === "string" && obj.title.trim()) return obj.title.trim();
  // Markdown H1
  const m1 = raw.match(/^\s*#\s+(.+)\s*$/m);
  if (m1) return m1[1].trim();
  // "Title:" line
  const m2 = raw.match(/^\s*Title\s*:\s*(.+)$/im);
  if (m2) return m2[1].trim();
  // First non-empty line (avoid URLs)
  const l = firstNonEmptyLine(raw);
  if (/^https?:\/\//i.test(l)) return "Untitled";
  return l.length > 120 ? l.slice(0, 117) + "..." : (l || "Untitled");
}
function pickMainTopic(raw, title) {
  // Explicit "Topic:" / "Main topic:" / "Headline:"
  const m = raw.match(/^\s*(?:Main\s*Topic|Topic|Headline)\s*:\s*(.+)$/im);
  if (m) return m[1].trim();
  // Next, look for a subheading under H1
  const h2 = raw.match(/^\s*##\s+(.+)\s*$/m);
  if (h2) return h2[1].trim();
  // Fallback: condensed title keywords
  return title.replace(/[:\-–—|].*$/,"").trim();
}
function extractUrls(raw) {
  const urls = raw.match(/https?:\/\/[^\s)>\]]+/g) || [];
  // strip trailing punctuation
  return uniq(urls.map(u => u.replace(/[.,);:\]]+$/,"")));
}
function sectionToList(raw, labels) {
  // Find a section by label and grab bullets/inline list that follows
  const lines = raw.split(/\n/);
  const out = [];
  const labelRe = new RegExp(`^\\s*(?:${labels.map(l=>l.replace(/[.*+?^${}()|[\]\\]/g,"\\$&")).join("|")})\\s*[:：]?\\s*$`, "i");
  for (let i=0; i<lines.length; i++) {
    if (labelRe.test(lines[i])) {
      // consume following bullets or comma/semicolon list on next non-empty line
      let j = i + 1;
      while (j < lines.length && !lines[j].trim()) j++;
      // bullets
      while (j < lines.length) {
        const ln = lines[j].trim();
        if (/^[-*•]\s+/.test(ln)) {
          out.push(ln.replace(/^[-*•]\s+/, "").trim());
          j++;
        } else {
          break;
        }
      }
      if (out.length === 0 && j < lines.length) {
        // try comma/semicolon list
        const maybe = lines[j].trim();
        if (maybe && !/^#/.test(maybe)) {
          maybe.split(/[;,]/).forEach(x => out.push(x.trim()));
        }
      }
      break;
    }
  }
  return uniq(out).filter(Boolean);
}
function fuzzyListByKeywords(raw, keywords) {
  // fallback: scan lines for any keyword and collect the phrase on that line
  const out = [];
  const re = new RegExp(`\\b(${keywords.join("|")})\\b`, "i");
  raw.split(/\n/).forEach(line => {
    const ln = line.trim();
    if (re.test(ln)) {
      // strip bullets/labels
      out.push(ln.replace(/^[-*•]\s+/,"").replace(/^\w[\w\s]*:\s*/,"").trim());
    }
  });
  return uniq(out);
}
function extractQuotes(raw) {
  // "Quote" — Name / “Quote” – Name / "Quote", said Name
  const quotes = [];
  const rx = /["“](.{10,280}?)["”]\s*(?:[-–—]\s*([A-Z][\w .'-]{1,80})|,\s*(?:said|says|according to)\s+([A-Z][\w .'-]{1,80}))?/g;
  let m;
  while ((m = rx.exec(raw)) !== null) {
    const text = m[1].trim();
    const by = (m[2] || m[3] || "").trim();
    quotes.push(by ? `${text} — ${by}` : text);
  }
  return uniq(quotes);
}

// ---------- read input ----------
let researchStr = "";
let researchObj = null;

// Accept several shapes: string at items[0].json.output; object; array => stringify
const j0 = items?.[0]?.json;
if (typeof j0?.output === "string") {
  researchStr = j0.output;
} else if (j0 && typeof j0.output === "object") {
  researchObj = j0.output;
  researchStr = text(j0.output);
} else if (typeof j0 === "string") {
  researchStr = j0;
} else if (j0 && (j0.research || j0.content || j0.text)) {
  researchStr = text(j0.research || j0.content || j0.text);
  // attempt parse if looks like JSON
  try { researchObj = JSON.parse(researchStr); } catch {}
} else if (Array.isArray(j0)) {
  researchStr = text(j0);
} else {
  // nothing usable; return empty structured skeleton
  const empty = {
    article_title: "Untitled",
    main_topic: "",
    key_findings: {
      industries_affected: [],
      jobs_created: [],
      jobs_displaced: [],
      skills_needed: [],
      expert_quotes: []
    },
    sources: [],
    full_research: ""
  };
  return [{ json: empty, pairedItem: { item: 0 } }];
}

researchStr = norm(researchStr);

// If research is valid JSON, keep parsed obj separately
if (!researchObj) {
  try {
    const maybe = JSON.parse(researchStr);
    if (maybe && typeof maybe === "object") researchObj = maybe;
  } catch {}
}

// ---------- dynamic extraction ----------
const article_title = pickTitle(researchObj || {}, researchStr);
const main_topic = pickMainTopic(researchStr, article_title);

// Primary labeled-section extraction
let industries_affected = sectionToList(researchStr, [
  "Industries Affected", "Affected Industries", "Industries Impacted"
]);
let jobs_created = sectionToList(researchStr, [
  "Jobs Created", "New Roles", "New Jobs"
]);
let jobs_displaced = sectionToList(researchStr, [
  "Jobs Displaced", "Roles at Risk", "Displaced Jobs"
]);
let skills_needed = sectionToList(researchStr, [
  "Skills Needed", "Required Skills", "Future Skills", "Key Skills"
]);

// Fallback fuzzy extraction (if lists are empty)
if (industries_affected.length === 0) {
  industries_affected = fuzzyListByKeywords(researchStr, [
    "industry","industries","sector","sectors","market","vertical"
  ]);
}
if (jobs_created.length === 0) {
  jobs_created = fuzzyListByKeywords(researchStr, [
    "hire","hiring","created","new role","new roles","engineer","specialist","architect","ethics","analyst"
  ]);
}
if (jobs_displaced.length === 0) {
  jobs_displaced = fuzzyListByKeywords(researchStr, [
    "displace","displaced","automation","at risk","replaced","redundant","outsourced"
  ]);
}
if (skills_needed.length === 0) {
  skills_needed = fuzzyListByKeywords(researchStr, [
    "skill","skills","literacy","problem","communication","emotional intelligence","reasoning","analysis"
  ]);
}

const expert_quotes = extractQuotes(researchStr);
const sources = extractUrls(researchStr);

// ---------- build result ----------
const structured_data = {
  article_title,
  main_topic,
  key_findings: {
    industries_affected,
    jobs_created,
    jobs_displaced,
    skills_needed,
    expert_quotes
  },
  sources,
  full_research: researchStr
};

// Return as ONE item; pair to item 0 to keep expressions working downstream
return [{ json: structured_data, pairedItem: { item: 0 } }];
